{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "partial",
      "summary_quote": "These signs include bullying, threats of violence, substance abuse, mental health concerns, self-harm, and suicidal thoughts.",
      "rationale": "Captures several examples but omits harassment, intimidation, and cyber-bullying and does not convey that both perpetrators and victims, and both makers and recipients of threats, are included."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "The bill would require each local education agency (LEA) and public charter school to use a computer-based system for teachers and staff to record students’ early warning signs of safety, health, or behavioral issues.",
      "rationale": "Conveys the required system, covered educational entities, teacher and staff use, and student information to be recorded."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "Schools would have to train teachers and staff to recognize and enter the signs.",
      "rationale": "In context, conveys the covered schools’ obligation to train teachers and staff in both identification and data entry."
    },
    {
      "proposition_id": "P4",
      "status": "partial",
      "summary_quote": "The system would have to meet the bill’s cited discipline and school safety requirements",
      "rationale": "Conveys alignment generally, but does not identify the separate § 49-6-4503 requirements or the obligation to align with each entity’s adopted SAVE Act safety plans."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "The system would have to meet the bill’s cited discipline and school safety requirements, keep the entered data",
      "rationale": "Together with the preceding description of teacher and staff data entry, conveys the system’s required data-receiving and retention functions."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "immediately notify personnel on the school’s threat assessment team when a sign is entered.",
      "rationale": "Conveys the notification trigger, immediacy, and required threat assessment team recipients."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "Those personnel would review the new notice and any earlier notices for the student and decide whether further action is needed.",
      "rationale": "Conveys review of both current and prior notifications and the determination whether further action is necessary."
    },
    {
      "proposition_id": "P8",
      "status": "full",
      "summary_quote": "Each LEA and public charter school would have to report annually to the department of education on data collected during the previous school year and any interventions provided.",
      "rationale": "Includes the reporting entities, recipient, annual frequency, reporting period, and required contents."
    },
    {
      "proposition_id": "P9",
      "status": "partial",
      "summary_quote": "Reports would have to comply with the cited privacy laws.",
      "rationale": "Conveys privacy compliance generally but does not identify the specified protections or include the additional requirement to comply with all other relevant privacy laws."
    },
    {
      "proposition_id": "P10",
      "status": "full",
      "summary_quote": "If an LEA or public charter school did not comply, the commissioner of education could withhold an amount of state funding the commissioner determines until it complies.",
      "rationale": "Conveys the noncompliance condition, commissioner’s discretionary authority and control over the amount, and withholding until compliance."
    },
    {
      "proposition_id": "P11",
      "status": "partial",
      "summary_quote": "The bill would also add references to public charter schools and their officials in Tennessee Code Annotated, §§ 49-6-2701 and 49-6-2702(b).",
      "rationale": "Identifies the amendment target and general charter-school expansion, but does not convey the specific inclusion of charter governing bodies and directors in subsection (e) or the scope of the other insertions."
    },
    {
      "proposition_id": "P12",
      "status": "full",
      "summary_quote": "The bill would also add references to public charter schools and their officials in Tennessee Code Annotated, §§ 49-6-2701 and 49-6-2702(b).",
      "rationale": "Identifies § 49-6-2702(b) and conveys its expansion to public charter schools; the exact possessive and nonpossessive insertion wording is not independently material."
    },
    {
      "proposition_id": "P13",
      "status": "full",
      "summary_quote": "It would take effect July 1, 2025.",
      "rationale": "States the effective date accurately."
    }
  ]
}
